from pathlib import Path
import json,re,html,shutil
from urllib.parse import quote,urlsplit
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'implementation';E=lambda v:html.escape(str(v),quote=True)
data=json.loads((OUT/'data/listings.json').read_text(encoding='utf-8'));listings=data['listings']
nav=[('listings','Properties'),('sellers','Sellers'),('buyers','Buyers'),('communities','Communities'),('about','Emad'),('team','Team'),('contact','Contact')]
header='<header class="header"><a class="brand" href="/" aria-label="Agent4Life Realty home"><img src="/assets/img/agent4life-logo.png" width="636" height="112" alt="Agent4Life Realty"></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">+</span></button><nav id="navigation" aria-label="Main navigation">'+''.join(f'<a href="/{p}/">{label}</a>' for p,label in nav)+'<a class="nav-contact" href="/home-value/">Home value ↗</a></nav></header>'
footer='''<footer><div class="wrap footer-links"><a href="/testimonials/">Client stories</a><a href="/home-value/">Home valuation</a><a href="/contact/?intent=Relocating">Relocation</a><a href="/listings/?status=sold">Sold properties</a><a href="https://www.instagram.com/realtoremadbasma/">Instagram</a><a href="https://www.facebook.com/Tracyrealestateandhomes">Facebook</a><a href="https://www.youtube.com/channel/UCcWFGqt9LnLadEw60vt4-yw">YouTube</a><a href="/privacy/">Privacy</a></div><div class="wrap"><p>© 2026 Agent4Life Realty. Emad A. Basma · DRE #01441193.</p><p>Equal Housing Opportunity</p><a href="#">Back to top ↑</a></div></footer>'''
def link(path,label,kind='primary'):return f'<a class="button {kind}" href="{E(path)}">{label} <span aria-hidden="true">↗</span></a>'
def picture(src,alt,cls=''):return f'<img class="{cls}" src="/{E(src)}" alt="{E(alt)}" width="1280" height="850" loading="lazy">'
def cta(title='Let’s put a plan behind it.',text='Talk directly with Emad about your next move.',path='/contact/',label='Talk with Emad'):return f'<section class="closing"><div class="wrap"><div><h2>{title}</h2><p>{text}</p></div>{link(path,label,"white")}</div></section>'
def hero(kicker,title,text,img=None):return f'<section class="inner-hero {"with-image" if img else ""}"><div class="wrap"><p class="kicker">{kicker}</p><h1>{title}</h1><p>{text}</p></div>{picture(img,title.replace("<br>"," ")) if img else ""}</section>'
def page(route,title,body,description=None):
 path=OUT/route/'index.html';path.parent.mkdir(parents=True,exist_ok=True)
 path.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080808"><title>{E(title)} | Agent4Life Realty</title><meta name="description" content="{E(description or title+' with Emad Basma and Agent4Life Realty in Tracy, California.')}"><link rel="canonical" href="https://agent4liferealty.com/{route}/"><link rel="icon" href="/assets/img/favicon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="/site.css"><script src="/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>{header}<main id="main">{body}</main>{footer}</body></html>''',encoding='utf-8')
def steps(items):return '<ol class="steps">'+''.join(f'<li><h3>{title}</h3><p>{text}</p></li>' for title,text in items)+'</ol>'
def faq(items):return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
def split(title,text):return f'<section class="section wrap editorial"><h2>{title}</h2><div>{text}</div></section>'
# Validate public listing data before creating any listing pages.
ids=set();slugs=set()
for p in listings:
 assert re.fullmatch(r'[a-z0-9-]+',p['slug']) and p['slug'] not in slugs,'Invalid or duplicate slug'
 assert p['id'] not in ids,'Duplicate listing id'
 ids.add(p['id']);slugs.add(p['slug'])
 assert p['status'] in ['active','pending','sold','showcase'],'Invalid status'
 assert all(isinstance(p[n],(int,float)) and p[n]>=0 for n in ['price','beds','sqft']),'Invalid number'
 for img in p['images']:assert (OUT/img).resolve().is_relative_to(OUT.resolve()) and (OUT/img).is_file(),f'Missing local image {img}'
 assert not p.get('tourUrl') or urlsplit(p['tourUrl']).scheme=='https','Tour URL must be HTTPS'

def card(p,featured=False):
 label={'active':'For sale','pending':'Pending','sold':'Sold','showcase':'Showcase'}[p['status']]
 media=picture(p['images'][0],p['address']) if p['images'] else '<div class="no-photo">Property photos coming soon</div>'
 return f'<a class="listing-card" href="/listings/{E(p["slug"])}/" data-status="{p["status"]}" data-city="{E(p["city"])}" data-price="{p["price"]}" data-beds="{p["beds"]}" data-address="{E(p["address"].lower())}"><div class="listing-image">{media}<span class="status">{label}</span></div><div class="listing-copy"><p class="listing-price">${p["price"]:,}</p><h2>{E(p["address"])}</h2><p>{E(p["city"])}, CA {E(p["zip"])}</p><p class="listing-facts">{p["beds"]} beds &nbsp; / &nbsp; {E(p["baths"])} baths &nbsp; / &nbsp; {p["sqft"]:,} sq. ft.</p><small>Listing office: {E(p["listingOffice"])}</small></div></a>'

page('sellers','Sell with Emad',hero('Sell with Emad','Your home deserves<br>a bigger introduction.','Personal preparation. Visible marketing. Direct guidance from the first conversation to the handoff.','assets/img/truck-pacheco.jpg')+split('Put a plan<br>before the sign.','<p class="lead">The right starting point is your situation—not a generic checklist.</p><p>Talk with Emad about your timeline, your home, and what comes next. Together, you can decide which preparations matter, how to present the property, and how to approach the market.</p>'+link('/home-value/','Request a home valuation'))+'<section class="soft section"><div class="wrap"><p class="kicker">From preparation to closing</p><h2>A clear path to market.</h2>'+steps([('Start with the home and your goals.','Walk through the property, discuss timing, and identify the information needed to shape a selling plan.'),('Prepare what matters.','Prioritize presentation and practical improvements. Emad can coordinate with trusted vendors as part of the plan you agree on.'),('Price with context.','Review comparable homes, property condition, and competing listings together. Pricing is a conversation grounded in the property and the market.'),('Give it a proper introduction.','Build a marketing plan around the home: property photography and video, open houses, and Agent4Life’s distinctive mobile billboard.'),('Understand the whole offer.','Review price alongside timing, contingencies, and the buyer’s terms. Emad helps you compare the details before deciding.'),('Stay informed through the finish.','Keep track of inspections, agreed repairs, deadlines, and the closing steps with clear communication along the way.')])+'</div></section>'+split('Before you list.',faq([('Do I need to renovate first?','Start with a walkthrough. Some homes benefit from focused preparation; others are better positioned with a different plan. Discuss the work and budget before spending.'),('Can I sell while planning my next purchase?','Yes—bring both timelines to the first conversation so Emad can help you consider how the two moves fit together.'),('How do I find out what my home could sell for?','Request a personal valuation. Share the address, condition, recent improvements, and timing so the discussion is specific to your home.')]))+cta('Let’s talk about your home.','Start with your address. Build the plan together.','/home-value/','Get a personal valuation'))
page('buyers','Buy with a plan',hero('Buying with Agent4Life','Find the home.<br>Know your next step.','A first purchase, more space, a different neighborhood—start with what your next home needs to do for you.','assets/img/city-mountain-house.jpg')+split('Start with<br>your priorities.','<p class="lead">A good search starts before the first showing.</p><p>Share your preferred areas, budget, timeline, and must-haves. Emad and the team help you focus your search, compare homes, and understand the decisions along the way.</p>'+link('/listings/','Explore properties'))+'<section class="soft section"><div class="wrap"><h2>From the first look<br>to the keys.</h2>'+steps([('Set the brief.','Separate essentials from nice-to-haves. Consider location, space, daily routines, and your timing.'),('Talk with a lender early.','If you plan to finance, discuss your budget and loan options with a lender. Ask Emad for an introduction if you need a starting point.'),('Visit and compare.','Look beyond photos. Take time to consider condition, layout, and how each property matches your priorities.'),('Prepare an offer.','Work through price, proposed timing, and terms with your agent before making a decision.'),('Follow through carefully.','Stay engaged with inspections, lender requests, and the agreed deadlines. Ask questions whenever something is unclear.'),('Plan the move.','Coordinate the final walkthrough, closing, and practical details of your move with the people involved.')])+'</div></section>'+split('Coming from<br>somewhere else?','<p class="lead">Let’s narrow down where to start.</p><p>Tell the team about your move, the areas you are considering, and when you can visit. They can help you organize a more focused search across Tracy, the Central Valley, and the Tri-Valley.</p>'+link('/contact/?intent=Relocating','Plan a relocation'))+cta())

