page('communities','Our communities',hero('Tracy roots. A wider reach.','Find your place.','Six communities. One team to help you explore what fits.')+'<div class="wrap community-jump">'+''.join(f'<a href="#{slug}">{name}</a>' for slug,name,_,_ in cities)+'</div>'+''.join(f'<section id="{slug}" class="city-section wrap">{picture("assets/img/city-"+slug+".jpg",name+", California")}<div><p class="kicker">{name}</p><h2>{title}</h2><p>{text}</p>{link("/listings/?city="+quote(name),"View "+name+" properties","dark")}<a class="inline-link" href="/contact/?intent=Buying&city={quote(name)}">Ask about {name}</a></div></section>' for slug,name,title,text in cities)+cta())

page('about','Meet Emad Basma',hero('Emad A. Basma','A name behind<br>every promise.','Founder of Agent4Life Realty. Real estate since 2004. A career built around service.','assets/img/emad-portrait.jpg')+split('Service is<br>the foundation.','<p class="lead">Before real estate, Emad served for 22 years as a Santa Clara County deputy sheriff.</p><p>That experience shaped his approach to representing clients: honest communication, careful attention, and responsibility for the work. His own homebuying experiences inspired him to enter real estate in 2004.</p><p>He works primarily with sellers and also represents buyers with a range of goals. His experience includes equity sales, foreclosures, and short sales. He is a Certified Distressed Property Expert and a graduate of California State University, Chico.</p><p>As the founder of Agent4Life, he leads a team that includes his son, Nizar, and daughter, Sonya. Together, they help clients navigate their next move with a personal approach.</p><p>DRE #01441193</p>')+'<section class="testimonial"><div class="wrap"><p class="kicker">The Agent4Life promise</p><h2>Superior service is not an option.<br>It’s a promise.</h2></div></section>'+split('See the promise<br>in practice.','<p>The billboard truck, property videos, and hands-on open houses make the marketing visible. Clear communication keeps the client at the center of the process.</p><div class="action-row">'+link('/sellers/','See the selling approach')+link('/testimonials/','Read client stories','dark')+'</div>')+cta())
