def form(valuation=False):
 purpose='<input type="hidden" name="intent" value="Home valuation">' if valuation else '<label>I’m looking to<select name="intent" id="intent"><option>Selling</option><option>Buying</option><option>Relocating</option><option>General question</option></select></label>'
 address='<label class="full">Property address<input name="address" autocomplete="street-address" required></label><label>City<input name="city" autocomplete="address-level2" required></label><label>ZIP code<input name="zip" autocomplete="postal-code" inputmode="numeric" pattern="[0-9]{5}" maxlength="5" required></label>' if valuation else '<label>Preferred area<input name="city" id="preferred-city" autocomplete="address-level2"></label>'
 return f'''<form class="request-form" data-request="{'valuation' if valuation else 'contact'}"><h2>{'Tell Emad about your home.' if valuation else 'Start the conversation.'}</h2><p>Fill this out to prepare an email. You’ll review it before opening your email app and sending it.</p><div class="fields">{purpose}<label>Your name<input name="name" autocomplete="name" required maxlength="120"></label><label>Email<input name="email" type="email" autocomplete="email" spellcheck="false" required maxlength="200"></label><label>Phone (optional)<input name="phone" type="tel" autocomplete="tel" maxlength="40"></label>{address}<label>Timing<select name="timing"><option>Just exploring</option><option>Within 3 months</option><option>3–6 months</option><option>6+ months</option></select></label><label class="full">{'Condition, improvements & anything else Emad should know' if valuation else 'How can we help?'}<textarea name="message" rows="5" maxlength="3000" required></textarea></label></div><p class="form-note">Your details stay in this page until you choose to send through your email app. <a href="/privacy/">Privacy details</a>.</p><button class="button primary" type="submit">Review my request <span aria-hidden="true">↗</span></button><noscript><p>To prepare a request here, enable JavaScript. Or email superiorservicerealtor@gmail.com directly.</p></noscript><div class="request-review" hidden tabindex="-1"><h3>Your email is ready to review.</h3><pre></pre><div class="action-row"><a class="button dark email-request" href="mailto:superiorservicerealtor@gmail.com">Open email app ↗</a><button class="button outline copy-request" type="button">Copy message</button><button class="button outline download-request" type="button">Save request</button></div><p class="request-status" aria-live="polite">Nothing has been sent. Send the message from your email app to complete your request.</p></div></form>'''
page('home-value','What is my home worth?',hero('A personal home valuation','Your home is more<br>than a number.','Tell Emad about the address, condition, and improvements. Start a valuation conversation specific to your property.')+'<section class="section wrap form-layout"><aside><h2>A better<br>starting point.</h2><p>This is a request for Emad’s review—not an instant automated estimate.</p><p>Include recent improvements and your timing. Those details help make the first conversation more useful.</p><h3>Prefer to talk?</h3><a class="big-phone" href="tel:+12099144751">209.914.4751</a></aside>'+form(True)+'</section>')
page('contact','Contact Emad',hero('Let’s talk','A direct line.<br>A real conversation.','Selling, buying, relocating, or just working out what comes next—reach Emad and the team here.')+'<section class="section wrap form-layout"><aside><p class="kicker">Emad A. Basma</p><h2>Your next move<br>starts here.</h2><a class="big-phone" href="tel:+12099144751">209.914.4751</a><p><a href="mailto:superiorservicerealtor@gmail.com">superiorservicerealtor@gmail.com</a></p><address>Agent4Life Realty<br>35 East 10th Street<br>Tracy, CA 95376</address><p>DRE #01441193</p><a class="inline-link" href="/team/">Contact another team member</a></aside>'+form()+'</section>')
page('privacy','Privacy & contact requests',hero('Your information','Your details.<br>Handled clearly.','How this version of the Agent4Life website handles contact requests and browsing.')+split('Contact requests.','<p>The contact and home valuation forms prepare a message in your browser. They do not submit information to Agent4Life automatically. You can review the text, copy it, save it to your device, or open it in your email app.</p><p>If you send the email, the recipient receives the information you included. Contact Agent4Life at <a href="mailto:superiorservicerealtor@gmail.com">superiorservicerealtor@gmail.com</a> with questions about a message you have sent or to request a correction.</p>')+split('Browsing<br>and services.','<p>This build does not include advertising trackers, analytics scripts, a newsletter subscription, or browser storage of your form details. The website host may process technical information when delivering pages.</p><p>Typography is loaded from Google Fonts, which requires a connection from your browser to Google’s servers. Links to social networks, virtual tours, or email applications take you to services with their own privacy practices.</p><p>This notice describes this version of the site. It should be updated if direct form delivery, analytics, or other services are added.</p>'))


